var i=`1032-ca-kho-to`;var t=`world-1032`;var s=`VN`;var n=`southeast-asia`;var r=4;var o=42;var u={en:`Ca Kho To`,ua:`Ка кхо то`};var h={en:`Ca Kho To is a dish from Vietnam prepared with shallot, garlic, catfish, fish sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ка кхо то, страва кухні країни В'єтнам, яку готують із таких продуктів: цибуля шалот, часник, сом, рибний соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 7 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 7 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:7,i:[[`white-granulated-sugar`,48,`g`],[`water`,35,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`shallot`,110,`g`],[`garlic`,4,`clove`],[`ground-black-pepper`,5,`g`],[`sunflower-oil`,20,`ml`]]},{en:`Braise the cut catfish gently in caramel sauce with fish sauce and coconut water until opaque and cooked through; reduce the sauce to a glossy coating.`,ua:`Обережно тушкуйте нарізаного сома в карамельному соусі з рибним соусом і кокосовою водою до повної готовності, уваривши до блискучої глазурі.`,t:[`braising`],m:25,i:[[`catfish`,700,`g`],[`fish-sauce`,58,`ml`],[`coconut-water`,300,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,35,`g`],[`serrano-pepper`,1,`pcs`]]}];var l={slug:i,id:t,country:`VN`,region:n,servings:4,minutes:42,title:u,text:h,steps:g};export{s as country,l as default,t as id,o as minutes,n as region,r as servings,i as slug,g as steps,h as text,u as title};